module HeartAndOxygen_system(
	clk,
	rst,
	uart_rx_from_heart,
	uart_rx_ai,
	uart_tx_to_heart,
	uart_tx_to_ai,
	tx_go_to_ai,
	data_to_ai,
	num_of_ai);

	//---Ports declearation: generated by Robei---
	input clk;
	input rst;
	input uart_rx_from_heart;
	input uart_rx_ai;
	output uart_tx_to_heart;
	output uart_tx_to_ai;
	output tx_go_to_ai;
	output [7:0] data_to_ai;
	output [7:0] num_of_ai;

	wire clk;
	wire rst;
	wire uart_rx_from_heart;
	wire uart_rx_ai;
	wire uart_tx_to_heart;
	wire uart_tx_to_ai;
	reg tx_go_to_ai;
	reg [7:0] data_to_ai;
	reg [7:0] num_of_ai;

	//----Code starts here: integrated by Robei-----
	wire   [7:0]  cmd_from_ai;
	wire             rx_sig;
	wire   [7:0]  spo_data;
	wire   [7:0]  heart_data;
	wire             ai_tx_done_flag;
	
	///////////////////////////////////////////////////////////
		wire [7:0] uart_data;               //接收的数据
		wire          uart_done; 
		wire          uart_get;                 //采样点
		 
		wire [7:0]  pack_cnt;                //字节计数
	   wire           pack_ing;	                //接收过程标志位
		wire           pack_done;            //帧接收完成标志位
		wire [7:0]  pack_num;             //接收到的字节数
		wire           recv_done;            //接收完一帧数据的接收和解码
		wire  [7:0] dataA;                    //解码后数据
		wire  [7:0] dataB;                    //解码后数据
	    wire [7:0] dataC;                    //解码后数据
	    wire [7:0] dataD;
	    wire          rx_flag_ai;//语音模块收到数据的标志位  
	    reg            rx_sig_d1;
	    reg            rx_sig_d2;
		 reg    [7:0]cur_a_state;
		 reg    [7:0] next_a_state;
		 
	//////////////////////////////////////////////////////////
	     parameter     IDLE_1 =      8'd21,
	                            ASK_SPO=    8'd5,
	                            ASK_HEART= 8'd6;
	////////////////////////////////////////////////////////
		 
		 always @(posedge clk or negedge rst)begin
		 	if(!rst) begin
		 		rx_sig_d1 <= 1'd0;
		 		rx_sig_d2 <= 1'd0;
		 	end
		 	else begin
		 		rx_sig_d1 <= rx_sig;
		 		rx_sig_d2 <= rx_sig_d1;
		 	end
		 end
		 
		 assign rx_sig_rise = ~rx_sig_d2 && rx_sig_d1;//数据送到标志
		 
	////////////////////////////////////////////////////////////
	//全域语音交互传感器互联
	always @(posedge clk or negedge rst)begin
		 	if(!rst)
		 		cur_a_state <= IDLE_1;
		 	else
		 		cur_a_state <= next_a_state;
		 end
		 
		 always @(*)begin
		 next_a_state = IDLE_1;
		           case(cur_a_state)
		               IDLE_1        :begin
		                   if(rx_sig_rise && cmd_from_ai == 8'h07 )
		                       next_a_state = ASK_SPO;
		                   else if(rx_sig_rise && cmd_from_ai == 8'h08 )
		                       next_a_state = ASK_HEART;    
		                   else
		                       next_a_state = IDLE_1;
		               end
		               ASK_SPO       :begin
		                   if(rx_sig_rise && cmd_from_ai == 8'h21 )
		                        next_a_state = IDLE_1;
		                   else if(ai_tx_done_flag == 1'b1)
		                        next_a_state = IDLE_1;
		                   else next_a_state = ASK_SPO;
		               end
		               ASK_HEART       :begin
		                   if(rx_sig_rise && cmd_from_ai == 8'h21 )
		                        next_a_state = IDLE_1;
		                   else if(ai_tx_done_flag == 1'b1)
		                        next_a_state = IDLE_1;
		                   else next_a_state = ASK_HEART;
		               end	               
		           endcase
		       end
		       
		 always @(posedge clk or negedge rst) begin
		     if(!rst) begin
		         tx_go_to_ai <= 1'b0;
		     end
		     else
		         case(cur_a_state)
		             ASK_SPO    :begin
		                 tx_go_to_ai <= 1'b1;
		                 data_to_ai <= spo_data; 
		                 num_of_ai <= 8'h03;
		             end
		             ASK_HEART    :begin
		                 tx_go_to_ai <= 1'b1;
		                 data_to_ai <= heart_data; 
		                 num_of_ai <= 8'h04;
		             end
		             IDLE_1     :begin
		                 tx_go_to_ai <= 1'b0;
		             end
		         endcase
		 end
	
	
	
	//---Module instantiation---
	uart_rx_from_ai UartRxFromAi(
		.clk(clk),
		.rst_n(rst),
		.rx(uart_rx_ai),
		.out_flag(rx_sig),
		.out_data(cmd_from_ai));

	heart_o2_top heart_o2_top2(
		.rst(rst),
		.uart_rx_from_heart(uart_rx_from_heart),
		.spo_data(spo_data),
		.heart_data(heart_data),
		.uart_tx_to_heart(uart_tx_to_heart),
		.clk(clk));

	uart_tx_ai uart_tx_ai3(
		.Clk(clk),
		.Reset_n(rst),
		.Tx_Go(tx_go_to_ai),
		.data(data_to_ai),
		.num_of_ai(num_of_ai),
		.uart_tx(uart_tx_to_ai),
		.Trans_Done(tx_done_flag));

endmodule    //HeartAndOxygen_system

